<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';requireLogin();$autoload=APP_ROOT.'/vendor/autoload.php';if(!is_file($autoload)){http_response_code(500);exit('Composer dependencies are not installed. Run composer install.');}require_once $autoload;
$y=(int)($_GET['year']??date('Y'));$m=(int)($_GET['month']??date('n'));[$start,$end]=monthBounds($y,$m);$search=trim((string)($_GET['search']??''));$cat=(int)($_GET['category']??0);$payment=$_GET['payment']??'';$type=$_GET['type']??'';$where=['t.user_id=?','t.transaction_date>=?','t.transaction_date<?'];$p=[currentUserId(),$start,$end];
if($search!==''){$where[]='t.description LIKE ?';$p[]='%'.$search.'%';}if($cat>0){$where[]='t.category_id=?';$p[]=$cat;}if(in_array($payment,['cash','debit_card','credit_card'],true)){$where[]='t.payment_method=?';$p[]=$payment;}if(in_array($type,['income','expense'],true)){$where[]='t.type=?';$p[]=$type;}
$s=db()->prepare("SELECT t.transaction_date,t.type,c.name category_name,t.payment_method,t.amount,t.description FROM transactions t JOIN categories c ON c.id=t.category_id WHERE ".implode(' AND ',$where)." ORDER BY t.transaction_date DESC,t.id DESC");$s->execute($p);
$book=new PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Transactions');$headers=['Date','Type','Category','Payment Method','Amount','Description'];foreach($headers as $i=>$h)$sheet->setCellValueByColumnAndRow($i+1,1,$h);$r=2;while($row=$s->fetch()){$vals=[$row['transaction_date'],$row['type'],$row['category_name'],ucwords(str_replace('_',' ',$row['payment_method'])),(float)$row['amount'],$row['description']];foreach($vals as $i=>$v)$sheet->setCellValueByColumnAndRow($i+1,$r,$v);$r++;}foreach(range('A','F') as $c)$sheet->getColumnDimension($c)->setAutoSize(true);$sheet->freezePane('A2');header('Content-Type:application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition:attachment; filename="transactions-'.$y.'-'.str_pad((string)$m,2,'0',STR_PAD_LEFT).'.xlsx"');$w=new PhpOffice\PhpSpreadsheet\Writer\Xlsx($book);$w->save('php://output');exit;
